<?php
session_start();require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/promotion_notifications.php';
$userId=(int)($_SESSION['user_id']??0);$role=$_SESSION['role']??'';
if(!$userId||!in_array($role,['publisher_admin','shop_admin'],true)){header('Location:/pages/login.php');exit;}
$sellerType=$role==='publisher_admin'?'publisher':'shop';
$sellerStmt=$sellerType==='publisher'?$pdo->prepare('SELECT p.publisher_id id,p.company_name name FROM publisher_staff ps JOIN publishers p ON p.publisher_id=ps.publisher_id WHERE ps.user_id=? LIMIT 1'):$pdo->prepare('SELECT s.shop_id id,s.shop_name name FROM shop_staff ss JOIN shops s ON s.shop_id=ss.shop_id WHERE ss.user_id=? LIMIT 1');
$sellerStmt->execute([$userId]);$seller=$sellerStmt->fetch(PDO::FETCH_ASSOC);if(!$seller){header('Location:/pages/login.php');exit;}
$sellerId=(int)$seller['id'];$seller_name=$seller['name'];$active_menu='promotions';
if(empty($_SESSION['promotion_csrf']))$_SESSION['promotion_csrf']=bin2hex(random_bytes(24));
$categoryStmt=$pdo->prepare("SELECT DISTINCT category FROM books WHERE seller_type=? AND seller_id=? AND category IS NOT NULL AND category<>'' ORDER BY category");$categoryStmt->execute([$sellerType,$sellerId]);$categories=$categoryStmt->fetchAll(PDO::FETCH_COLUMN);
$bookStmt=$pdo->prepare("SELECT book_id,title,author FROM books WHERE seller_type=? AND seller_id=? AND status<>'hidden' ORDER BY title");$bookStmt->execute([$sellerType,$sellerId]);$sellerBooks=$bookStmt->fetchAll(PDO::FETCH_ASSOC);$allowedBookIds=array_map('intval',array_column($sellerBooks,'book_id'));
$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals($_SESSION['promotion_csrf'],(string)($_POST['csrf_token']??'')))throw new RuntimeException('แบบฟอร์มหมดอายุ กรุณาลองใหม่');
  if(isset($_POST['create_promotion'])){
   $name=trim((string)($_POST['promotion_name']??''));$type=($_POST['discount_type']??'')==='fixed'?'fixed':'percentage';$scope=in_array($_POST['scope_type']??'all',['all','category','books'],true)?$_POST['scope_type']:'all';$value=(float)($_POST['discount_value']??0);$minQty=max(1,(int)($_POST['minimum_quantity']??1));$minAmount=max(0,(float)($_POST['minimum_amount']??0));$max=trim((string)($_POST['maximum_discount']??''));$start=str_replace('T',' ',(string)($_POST['starts_at']??''));$end=str_replace('T',' ',(string)($_POST['ends_at']??''));
   if($name===''||$value<=0||($type==='percentage'&&$value>100)||!strtotime($start)||!strtotime($end)||strtotime($end)<=strtotime($start))throw new RuntimeException('กรุณาตรวจสอบชื่อ ส่วนลด และช่วงเวลาโปรโมชั่น');
   $targets=[];$targetType='';
   if($scope==='category'){$targets=array_values(array_intersect($categories,array_map('strval',$_POST['target_categories']??[])));$targetType='category';}
   elseif($scope==='books'){$targets=array_values(array_intersect($allowedBookIds,array_map('intval',$_POST['target_books']??[])));$targetType='book';}
   if($scope!=='all'&&!$targets)throw new RuntimeException('กรุณาเลือกหมวดหมู่หรือหนังสือที่ร่วมโปรโมชั่นอย่างน้อย 1 รายการ');
   $pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO seller_promotions(seller_type,seller_id,promotion_name,description,scope_type,discount_type,discount_value,minimum_quantity,minimum_amount,maximum_discount,starts_at,ends_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');
   $stmt->execute([$sellerType,$sellerId,$name,trim((string)($_POST['description']??''))?:null,$scope,$type,$value,$minQty,$minAmount,$max===''?null:max(0,(float)$max),$start,$end,$userId]);
   $promotionId=(int)$pdo->lastInsertId();if($targets){$targetInsert=$pdo->prepare('INSERT INTO seller_promotion_targets(promotion_id,target_type,target_value) VALUES(?,?,?)');foreach($targets as $target)$targetInsert->execute([$promotionId,$targetType,(string)$target]);}
   $scopeLabel='สินค้าทั้งร้าน';
   if($scope==='category')$scopeLabel='หมวด '.implode(', ',$targets);
   elseif($scope==='books'){$bookNames=[];foreach($sellerBooks as $book)if(in_array((int)$book['book_id'],$targets,true))$bookNames[]=$book['title'];$scopeLabel='หนังสือ/ซีรีส์ '.implode(', ',$bookNames);}
   $discountLabel=$type==='percentage'?'ลด '.number_format($value,0).'%':'ลด '.number_format($value,2).' บาท';
   $conditions=[];if($minQty>1)$conditions[]='ซื้อครบ '.$minQty.' เล่ม';if($minAmount>0)$conditions[]='ยอดครบ '.number_format($minAmount,2).' บาท';
   $postContent="🎉 โปรโมชั่นใหม่: {$name}\n{$scopeLabel} {$discountLabel}".($conditions?' เมื่อ'.implode(' และ ',$conditions):'')."\nเริ่ม ".date('d/m/Y H:i',strtotime($start))." ถึง ".date('d/m/Y H:i',strtotime($end));if(trim((string)($_POST['description']??''))!=='')$postContent.="\n".trim((string)$_POST['description']);
   $postTable=$sellerType==='shop'?'shop_posts':'publisher_posts';$ownerColumn=$sellerType==='shop'?'shop_id':'publisher_id';$post=$pdo->prepare("INSERT INTO {$postTable}({$ownerColumn},promotion_id,content,background_color,is_bold) VALUES(?,?,?,'#FFF1F5',1)");$post->execute([$sellerId,$promotionId,$postContent]);
   $pdo->commit();$promotionStmt=$pdo->prepare('SELECT * FROM seller_promotions WHERE promotion_id=?');$promotionStmt->execute([$promotionId]);$createdPromotion=$promotionStmt->fetch(PDO::FETCH_ASSOC);$delivery=$createdPromotion?wanawanNotifyPromotionFollowers($pdo,$createdPromotion,$seller['name'],$sellerType,$sellerId):['followers'=>0,'email'=>0,'line'=>0];$success='สร้างโปรโมชั่นและประกาศหน้าโปรไฟล์เรียบร้อยแล้ว · แจ้งผู้ติดตาม '.number_format($delivery['followers']).' คน';
  }elseif(isset($_POST['toggle_promotion'])){$pdo->prepare('UPDATE seller_promotions SET is_active=1-is_active WHERE promotion_id=? AND seller_type=? AND seller_id=?')->execute([(int)$_POST['promotion_id'],$sellerType,$sellerId]);$success='อัปเดตสถานะโปรโมชั่นแล้ว';
  }elseif(isset($_POST['delete_promotion'])){$pdo->prepare('DELETE FROM seller_promotions WHERE promotion_id=? AND seller_type=? AND seller_id=?')->execute([(int)$_POST['promotion_id'],$sellerType,$sellerId]);$success='ลบโปรโมชั่นแล้ว';}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$stmt=$pdo->prepare('SELECT * FROM seller_promotions WHERE seller_type=? AND seller_id=? ORDER BY created_at DESC');$stmt->execute([$sellerType,$sellerId]);$promotions=$stmt->fetchAll(PDO::FETCH_ASSOC);
if($promotions){$targetStmt=$pdo->prepare('SELECT target_type,target_value FROM seller_promotion_targets WHERE promotion_id=?');foreach($promotions as &$promotion){$targetStmt->execute([$promotion['promotion_id']]);$promotion['targets']=$targetStmt->fetchAll(PDO::FETCH_ASSOC);}unset($promotion);}
function promoStatus(array $p):array{if(!$p['is_active'])return['ปิดใช้งาน','off'];if(strtotime($p['starts_at'])>time())return['กำลังจะเริ่ม','soon'];if(strtotime($p['ends_at'])<time())return['สิ้นสุดแล้ว','ended'];return['กำลังใช้งาน','on'];}
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>จัดการโปรโมชั่น - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--text-dark);font-family:var(--font-family);display:flex}.main{margin-left:260px;padding:48px 38px;width:calc(100% - 260px)}h1{color:var(--secondary-color)}.sub{color:var(--text-muted)}.grid{display:grid;grid-template-columns:390px 1fr;gap:24px;margin-top:25px}.card{border:1px solid #e3c3ce;border-radius:15px;padding:24px;background:#fff}.card h2{margin-top:0;color:var(--secondary-color);font-size:20px}.field{margin:13px 0}.field label{display:block;font-size:13px;margin-bottom:6px;color:#735d65}.field input,.field select,.field textarea{width:100%;padding:11px;border:1px solid #d8c9ce;border-radius:8px;font:inherit}.field textarea{min-height:75px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{border:0;border-radius:8px;padding:11px 15px;background:var(--secondary-color);color:#fff;font:inherit;font-weight:700;cursor:pointer}.full{width:100%;margin-top:8px}.promo{border:1px solid #ead6dd;border-radius:12px;padding:18px;margin-bottom:12px}.promo-head{display:flex;justify-content:space-between;gap:15px}.promo h3{margin:0;color:#6e4655}.badge{border-radius:20px;padding:5px 9px;font-size:11px;font-weight:700}.on{background:#e5f3df;color:#36703c}.off,.ended{background:#eee;color:#777}.soon{background:#fff1cf;color:#8b6816}.detail{color:#75676c;font-size:13px;line-height:1.7;margin:10px 0}.actions{display:flex;gap:8px}.actions form{margin:0}.secondary{background:#fff;color:var(--secondary-color);border:1px solid var(--secondary-color);padding:7px 10px}.danger{color:#a33;border-color:#d99}.notice{padding:12px 15px;border-radius:8px;margin-top:15px}.ok{background:#e8f5e4;color:#39703a}.bad{background:#fde7e2;color:#a33}.empty{text-align:center;padding:60px 20px;color:#999}@media(max-width:900px){body{display:block}.main{margin:0;width:100%;padding:25px 14px}.grid{grid-template-columns:1fr}}@media(max-width:500px){.two{grid-template-columns:1fr}}
</style></head><body><?php include __DIR__.'/../components/sidebar.php';?><main class="main"><h1>จัดการโปรโมชั่น</h1><p class="sub">สร้างส่วนลดสำหรับสินค้าทั้งร้าน ระบบจะเลือกโปรโมชั่นที่คุ้มที่สุดให้ลูกค้าอัตโนมัติ</p><?php if($success):?><div class="notice ok"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error)?></div><?php endif;?><div class="grid"><section class="card"><h2>สร้างโปรโมชั่นใหม่</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['promotion_csrf'])?>"><div class="field"><label>ชื่อโปรโมชั่น</label><input name="promotion_name" placeholder="เช่น ซื้อครบ 3 เล่ม ลด 50%" required maxlength="150"></div><div class="field"><label>รายละเอียด</label><textarea name="description" placeholder="ข้อความที่ต้องการแสดงให้ลูกค้าเห็น"></textarea></div><div class="two"><div class="field"><label>รูปแบบส่วนลด</label><select name="discount_type"><option value="percentage">เปอร์เซ็นต์ (%)</option><option value="fixed">จำนวนเงิน (บาท)</option></select></div><div class="field"><label>มูลค่าส่วนลด</label><input type="number" name="discount_value" min="0.01" step="0.01" required></div></div><div class="two"><div class="field"><label>จำนวนขั้นต่ำ (เล่ม)</label><input type="number" name="minimum_quantity" min="1" value="1" required></div><div class="field"><label>ยอดซื้อขั้นต่ำ (บาท)</label><input type="number" name="minimum_amount" min="0" step="0.01" value="0"></div></div><div class="field"><label>ลดสูงสุด (บาท) — ไม่กำหนดได้</label><input type="number" name="maximum_discount" min="0" step="0.01"></div><div class="two"><div class="field"><label>เริ่มโปรโมชั่น</label><input type="datetime-local" name="starts_at" value="<?=date('Y-m-d\TH:i')?>" required></div><div class="field"><label>สิ้นสุดโปรโมชั่น</label><input type="datetime-local" name="ends_at" value="<?=date('Y-m-d\TH:i',strtotime('+7 days'))?>" required></div></div><button class="btn full" name="create_promotion">สร้างโปรโมชั่น</button></form></section><section class="card"><h2>โปรโมชั่นของร้าน</h2><?php if(!$promotions):?><div class="empty">ยังไม่มีโปรโมชั่น เริ่มสร้างโปรโมชั่นแรกได้เลย</div><?php else:foreach($promotions as $p):[$label,$class]=promoStatus($p);?><article class="promo"><div class="promo-head"><h3><?=htmlspecialchars($p['promotion_name'])?></h3><span class="badge <?=$class?>"><?=$label?></span></div><div class="detail"><?=htmlspecialchars($p['description']?:'โปรโมชั่นสินค้าทั้งร้าน')?><br><strong><?=$p['discount_type']==='percentage'?'ลด '.number_format($p['discount_value'],0).'%':'ลด ฿'.number_format($p['discount_value'],2)?></strong> · ซื้ออย่างน้อย <?=number_format($p['minimum_quantity'])?> เล่ม<?php if($p['minimum_amount']>0):?> · ยอดขั้นต่ำ ฿<?=number_format($p['minimum_amount'],2)?><?php endif;?><br><?=date('d/m/Y H:i',strtotime($p['starts_at']))?> – <?=date('d/m/Y H:i',strtotime($p['ends_at']))?></div><div class="actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['promotion_csrf'])?>"><input type="hidden" name="promotion_id" value="<?=$p['promotion_id']?>"><button class="btn secondary" name="toggle_promotion"><?=$p['is_active']?'ปิดใช้งาน':'เปิดใช้งาน'?></button></form><form method="post" onsubmit="return confirm('ลบโปรโมชั่นนี้ใช่หรือไม่?')"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['promotion_csrf'])?>"><input type="hidden" name="promotion_id" value="<?=$p['promotion_id']?>"><button class="btn secondary danger" name="delete_promotion">ลบ</button></form></div></article><?php endforeach;endif;?></section></div></main></body></html>
